// Assembles registry.json from registry/*.json (icons.json is generated by
// scripts/generate-icons.mjs), then (unless --check) runs `shadcn build` into
// public/r, which the docs site serves beside motion's and UI's items. The
// icons install at components/youj/icons/, and their imports from
// @youj/motion become youj-core's files (scripts/source-registry.mjs).
//
//   node scripts/build-registry.mjs          write registry.json + public/r
//   node scripts/build-registry.mjs --check  validate only; exit 1 on problems
import { join } from 'node:path'
import { buildSourceRegistry } from '../../../scripts/source-registry.mjs'

buildSourceRegistry(join(import.meta.dirname, '..'), 'youj-icons')
